from typing import Tuple, Dict

def format_duration(
    seconds: int, 
    format: str = 'human',
    precision: int = 2
) -> Tuple[str, Dict[str, int]]:
    """
    格式化时长。
    """
    if seconds < 0:
        raise ValueError('Seconds must be non-negative')

    # 计算各时间单位
    days = seconds // 86400
    remaining = seconds % 86400
    hours = remaining // 3600
    remaining = remaining % 3600
    minutes = remaining // 60
    secs = remaining % 60

    components = {
        'days': days,
        'hours': hours,
        'minutes': minutes,
        'seconds': secs
    }

    # 根据格式生成字符串
    if format == 'human':
        parts = []
        if days > 0:
            parts.append(f'{days} day{"s" if days != 1 else ""}')
        if hours > 0 and len(parts) < precision:
            parts.append(f'{hours} hour{"s" if hours != 1 else ""}')
        if minutes > 0 and len(parts) < precision:
            parts.append(f'{minutes} min')
        if secs > 0 and len(parts) < precision:
            parts.append(f'{secs} sec')

        formatted = ' '.join(parts) if parts else '0 sec'

    elif format == 'cn':
        parts = []
        if days > 0:
            parts.append(f'{days}天')
        if hours > 0 and len(parts) < precision:
            parts.append(f'{hours}小时')
        if minutes > 0 and len(parts) < precision:
            parts.append(f'{minutes}分钟')
        if secs > 0 and len(parts) < precision:
            parts.append(f'{secs}秒')

        formatted = ''.join(parts) if parts else '0秒'

    elif format == 'compact':
        parts = []
        if days > 0:
            parts.append(f'{days}d')
        if hours > 0 and len(parts) < precision:
            parts.append(f'{hours}h')
        if minutes > 0 and len(parts) < precision:
            parts.append(f'{minutes}m')
        if secs > 0 and len(parts) < precision:
            parts.append(f'{secs}s')

        formatted = ' '.join(parts) if parts else '0s'

    elif format == 'iso':
        # ISO 8601 格式: P[n]DT[n]H[n]M[n]S
        parts = ['P']
        if days > 0:
            parts.append(f'{days}D')
        if hours > 0 or minutes > 0 or secs > 0:
            parts.append('T')
            if hours > 0:
                parts.append(f'{hours}H')
            if minutes > 0:
                parts.append(f'{minutes}M')
            if secs > 0:
                parts.append(f'{secs}S')

        formatted = ''.join(parts) if len(parts) > 1 else 'PT0S'

    else:
        raise ValueError(f'Unknown format: {format}')

    return formatted, components
